sys_variable_value.value:
(function execute(inputs, outputs) {
    var panelIds = (inputs.panelists || '').split(',');
    for (var i = 0; i < panelIds.length; i++) {
        var panelId = panelIds[i].trim();
        if (panelId) {
            var fb = new GlideRecord('x_snc_aegis_interview_feedback');
            fb.initialize();
            fb.setValue('interview', inputs.interview_sys_id);
            fb.setValue('panellist', panelId);
            fb.setValue('feedback_status', 'PENDING');
            // BR-8 automatically computes breach_at = now + 48 hours on insert!
            fb.insert();
        }
    }
})(inputs, outputs);

